{contact?<label>{txt(c.contact.contactTypeLabel,l)}<select name="contactType" required={c.contact.contactTypeRequired!==false}><option value="">{t("اختر نوع التواصل","Choose contact type")}</option>{(c.contact.contactTypes||[]).filter((x:any)=>x.enabled!==false).map((x:any)=><option value={x.id} key={x.id}>{txt(x.label,l)}</option>)}</select></label>:<><div className="fields-row"><label>{txt(c.form.cityLabel,l)}<input name="city" required={c.form.locationRequired!==false}/></label><label>{txt(c.form.districtLabel,l)}<input name="district" required={c.form.locationRequired!==false}/></label></div><label>{txt(c.form.contractTypeLabel,l)}<select name="contractType" required={c.form.contractTypeRequired!==false}><option value="">{t("اختر نوع العقد","Choose contract type")}</option>{(c.form.contractTypes||[]).filter((x:any)=>x.enabled!==false).map((x:any)=><option value={x.id} key={x.id}>{txt(x.label,l)}</option>)}</select></label><label>{t("الجنسية المطلوبة","Preferred nationality")}<select value={nat} onChange={e=>setNat(e.target.value)} required={c.form.nationalityRequired}><option value="">{t("اختر الجنسية","Choose nationality")}</option>{c.nationalities.filter((n:any)=>n.enabled).map((n:any)=><option value={n.id} key={n.id}>{n.flag} {txt(n.name,l)}</option>)}</select></label><fieldset><legend>{t("الخدمات المطلوبة","Services needed")}</legend><div className="checkbox-grid">{c.services.filter((s:any)=>s.enabled&&s.inForm).map((s:any)=><label className={`check-option ${services.includes(s.id)?"checked":""}`} key={s.id}><input type="checkbox" checked={services.includes(s.id)} onChange={e=>setServices(v=>e.target.checked?[...v,s.id]:v.filter(i=>i!==s.id))}/><span>{txt(s.name,l)}</span></label>)}</div><small>{t("يمكنك اختيار أكثر من خدمة","You can choose more than one service")}</small></fieldset></>}
