function Chat({c,l,standalone=false}:any){const [open,setOpen]=useState(standalone);const [messages,setMessages]=useState<any[]>([]);const [input,setInput]=useState("");const [busy,setBusy]=useState(false);const [error,setError]=useState("");const [id]=useState(()=>{if(typeof window!=="undefined"){const q=new URLSearchParams(window.location.search).get("conversation");if(q&&/^[a-f0-9-]{36}$/.test(q))return q;}return "local-"+Date.now().toString(36)+"-"+Math.random().toString(36).slice(2)});const [awaitingPhone,setAwaitingPhone]=useState(false);const [awaitingCallbackPhone,setAwaitingCallbackPhone]=useState(false);const normalize=(s:any)=>String(s||"").toLowerCase().normalize("NFKC").replace(/[؟?.,!،؛:]/g,"").replace(/\s+/g," ").trim();const detectArabic=(value:string)=>{const s=String(value||"");const arabicCount=(s.match(/[\u0600-\u06ff]/g)||[]).length;const latinCount=(s.match(/[A-Za-z]/g)||[]).length;return arabicCount>latinCount||(!arabicCount&&!latinCount&&l==="ar")};const answerFor=(message:string)=>{const m=normalize(message);const replyAr=detectArabic(message);const responseLang=replyAr?"ar":"en";const phone=String(c?.contact?.phone||c?.contact?.phone2||c?.contact?.whatsapp||"").trim();const arabicGreeting=/^(هلا|اهلا|أهلا|مرحبا|مرحباً|السلام عليكم|سلام|هاي|يا هلا|صباح الخير|مساء الخير)/.test(m);const englishGreeting=/^(hi|hello|hey|good morning|good evening|how are you|greetings)\b/.test(m);if(arabicGreeting||englishGreeting)return replyAr?"أهلاً بك في بوابة جدة، أنا شهد. كيف أقدر أساعدك اليوم؟":"Welcome to Jeddah Gate. I’m Shahd. How can I help you today?";const thanks=/\b(thanks|thank you|thx)\b/.test(m)||/شكرا|شكرًا|مشكورة|مشكور/.test(m);if(thanks)return replyAr?"العفو، يسعدني مساعدتك.":"You’re welcome. I’m happy to help.";const answers=[...(c.bot.faqs||[]),...(c.faq||[])];const words=(value:any)=>normalize(value).split(/\s+/).filter((w:string)=>w.length>1);const synonymGroups=responseLang==="ar"?[['طلب','تقديم','استقدام','معاملة'],['تتبع','متابعة','حالة','اين','أين'],['خدمة','خدمات','احتياج'],['جنسية','جنسيات','بلد'],['سعر','اسعار','أسعار','تكلفة','رسوم'],['هاتف','جوال','رقم','اتصال','تواصل']]:[['request','application','recruitment','apply'],['track','status','follow','application'],['service','support','need'],['nationality','country','worker'],['price','cost','fee','fees'],['phone','mobile','call','contact']];const expanded=(value:any)=>{const base=words(value);return Array.from(new Set([...base,...synonymGroups.filter(g=>g.some(x=>base.includes(x))).flat()]));};const inputWords=expanded(m);const matched=answers.map((f:any)=>{const q=normalize(f.question?.[responseLang]||f.question);const keyWords=String(f.keywords||"").split(",").flatMap((x:string)=>expanded(x));const target=Array.from(new Set([...expanded(q),...keyWords]));const exact=q&&(q===m||q.includes(m)||m.includes(q));const overlap=target.filter((w:string)=>inputWords.includes(w)).length;const score=exact?100:overlap/Math.max(1,Math.min(inputWords.length,target.length));return {...f,score}}).filter((f:any)=>f.score>0).sort((a:any,b:any)=>b.score-a.score)[0];if(matched&&matched.score>=0.34)return String(matched.answer?.[responseLang]||matched.answer||"");const smart=smartAnswer(m,c,l);if(smart)return smart;const fallback=String(c.bot.fallback?.[responseLang]||(replyAr?"سأطلب من أحد ممثلي خدمة العملاء المتابعة معك قريباً.":"I will ask one of our live agents to answer you shortly."));return fallback+(phone?(replyAr?" يمكنك الاتصال بفريق المبيعات على رقم ":" You can call our sales team at ")+phone:"")};;const phoneDigits=(v:any)=>String(v||"").replace(/\D/g,"");const isGreeting=(v:string)=>/^(hi|hello|hey|good morning|good evening|how are you|greetings)\b/.test(normalize(v))||/^(هلا|اهلا|أهلا|مرحبا|مرحباً|السلام عليكم|سلام|هاي|يا هلا|صباح الخير|مساء الخير)/.test(normalize(v));const wantsCallback=(v:string)=>{const m=normalize(v);return /(call me|call back|callback|contact me|speak to (someone|an agent)|live agent|support team|sales team|representative|agent)/.test(m)||/(اتصل بي|اتصال بي|تواصل معي|خدمة العملاء|الدعم|المبيعات|موظف|ممثل|أحد من الشركة|حد يتصل)/.test(m)};const wantsTracking=(v:string)=>{const m=normalize(v);if(/process|procedure|steps|how to (submit|place|make)|طريقة|خطوات|إجراءات|آلية/.test(m))return false;return /track|tracking|status|follow|order/.test(m)||/تتبع|متابعة|حالة|طلبي|طلبى|الطلب/.test(m)};const append=(items:any[])=>setMessages(prev=>[...prev,...items].slice(-100));const ask=(message:string)=>{try{const clean=String(message||"").trim();if(!clean)return;const replyAr=detectArabic(clean);setError("");const digits=phoneDigits(clean);if(awaitingCallbackPhone&&!isGreeting(clean)){if(digits.length<8){append([{role:"user",text:clean},{role:"assistant",text:replyAr?"يرجى إرسال رقم الجوال حتى يتواصل معك فريق الدعم.":"Please send your mobile number so our support team can contact you."}]);setInput("");return}setAwaitingCallbackPhone(false);const transcript=[...messages,{role:"user",text:clean}];append([{role:"user",text:clean},{role:"assistant",text:replyAr?"شكراً لك. أرسلت طلب التواصل إلى فريق الدعم، وسيتواصل معك قريباً.":"Thank you. I’ve sent your callback request to our support team. They’ll contact you shortly."}]);setInput("");fetch("/api/chat-callback",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({phone:digits,lang:replyAr?"ar":"en",messages:transcript})}).then(r=>r.json()).then((d:any)=>{if(!d.ok)append([{role:"assistant",text:replyAr?"تعذر إرسال الطلب حالياً. يرجى الاتصال بفريق المبيعات مباشرة.":"I couldn’t send the request right now. Please call our sales team directly."}])}).catch(()=>append([{role:"assistant",text:replyAr?"تعذر إرسال الطلب حالياً. يرجى الاتصال بفريق المبيعات مباشرة.":"I couldn’t send the request right now. Please call our sales team directly."}]));return}if(awaitingPhone&&!isGreeting(clean)){if(digits.length<8){append([{role:"user",text:clean},{role:"assistant",text:replyAr?"يرجى إرسال رقم الجوال المسجل في الطلب.":"Please send the mobile number used in your request."}]);setInput("");return}setAwaitingPhone(false);append([{role:"user",text:clean},{role:"assistant",text:replyAr?"لحظة، أتحقق من حالة طلبك…":"One moment, I’m checking your request status…"}]);setInput("");fetch("/api/chat-status",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({phone:digits,lang:l})}).then(r=>r.json()).then((d:any)=>{const text=d.found?(replyAr?"حالة طلبك "+d.reference+" هي: "+d.stage:"Your request "+d.reference+" is: "+d.stage):(replyAr?"لم أجد طلباً مرتبطاً بهذا الرقم. يرجى التأكد من الرقم أو التواصل مع فريق المبيعات.":"I couldn’t find a request linked to this number. Please check it or contact our sales team.");append([{role:"assistant",text}])}).catch(()=>append([{role:"assistant",text:replyAr?"تعذر التحقق حالياً. يرجى التواصل مع فريق المبيعات.":"I couldn’t check it right now. Please contact our sales team."}]));return}if(wantsCallback(clean)){setAwaitingCallbackPhone(true);append([{role:"user",text:clean},{role:"assistant",text:replyAr?"بالتأكيد. أرسل رقم جوالك وسأطلب من فريق الدعم التواصل معك.":"Absolutely. Please send your mobile number and I’ll ask our support team to call you."}]);setInput("");return}if(wantsTracking(clean)){setAwaitingPhone(true);append([{role:"user",text:clean},{role:"assistant",text:replyAr?"نعم بالتأكيد، أرسل رقم الجوال المستخدم في الطلب وسأتحقق من حالته.":"Yes, certainly. Please provide the mobile number used in the request and I’ll check its status."}]);setInput("");return}const answer=answerFor(clean);append([{role:"user",text:clean},{role:"assistant",text:answer}]);setInput("")}catch{append([{role:"user",text:String(message||"")},{role:"assistant",text:detectArabic(message)?"سأطلب من فريق الدعم المتابعة معك قريباً.":"I’ll ask our support team to follow up with you shortly."}])}};const bot=c.bot;const questions=[...(bot.faqs||[]),...(c.faq||[])].filter((q:any)=>q?.question).slice(0,4);
return <div className={`chat-shell ${bot.position} ${standalone?"standalone":""}`} style={{"--bot-size":bot.size*bot.launcherScale+"px","--bot-mobile-size":bot.mobileSize*bot.launcherScale+"px","--ring-color":bot.ringColor,"--ring-speed":Math.max(2,bot.ringSeconds)+"s","--bot-offset":bot.offset+"px","--bot-color":bot.color,"--bot-bubble-bg":bot.bubbleBackground||"#f0b400","--bot-bubble-text":bot.bubbleTextColor||"#ffffff","--bot-bubble-border":bot.bubbleBorderColor||bot.bubbleBackground||"#f0b400","--chat-width":bot.width+"px"} as any}>
{open&&<div className="chat-window"><div className="chat-header"><Image src={bot.avatar} alt={txt(bot.name,l)}/><div><strong>{txt(bot.name,l)}</strong><small>{l==="ar"?"المساعدة الافتراضية":"Virtual assistant"}</small></div><div className="chat-tools">{!standalone&&<button type="button" onClick={()=>setOpen(false)} aria-label="Close chat"><X size={18}/></button>}</div></div><div className="chat-messages" aria-live="polite"><p className="chat-bubble assistant">{txt(bot.welcome,l)}</p>{messages.map((m,i)=><p key={i} className={`chat-bubble ${m.role}`}>{m.text}</p>)}<div className="chat-questions">{questions.length>0&&<><small>{l==="ar"?"أسئلة سريعة":"Quick questions"}</small>{questions.map((q:any,i:number)=><button key={i} type="button" onClick={(e)=>{e.preventDefault();e.stopPropagation();ask(txt(q.question,l))}}>{txt(q.question,l)}</button>)}</>}</div><div className="quick-actions">{bot.quickActions.map((p:string)=><a key={p} href={`/${l}/${p}`}>{txt(pageNames[p],l)}</a>)}</div>{error&&<p className="error">{error}</p>}</div><form className="chat-input" role="group" onSubmitCapture={e=>{e.preventDefault();e.stopPropagation()}} onSubmit={e=>{e.preventDefault();e.stopPropagation();ask(input)}}><input value={input} onChange={e=>setInput(e.target.value)} type="text" onKeyDownCapture={e=>{if(e.key==="Enter"){e.preventDefault();e.stopPropagation();ask(input)}}} maxLength={1000} aria-label="Message" placeholder={l==="ar"?"اكتب رسالتك هنا…":"Type your message…"}/><button type="button" onClick={e=>{e.preventDefault();e.stopPropagation();ask(input)}} aria-label="Send"><Send size={18}/></button></form><a className="chat-handoff" href={`/${l}/contact`}>{txt(bot.handoff,l)}</a></div>}
{!standalone&&<button type="button" className={`bot-launcher ${bot.motion?"bot-motion":""} ${bot.ring?"attention-ring":""}`} onClick={()=>setOpen(!open)} aria-expanded={open} aria-label={txt(bot.name,l)}>{bot.bubble&&!open&&<span>{l==="ar"?"أنا شهد، كيف أساعدك؟":"Hi, I'm Shahd. Need help?"}</span>}<Image src={bot.body} alt={txt(bot.name,l)}/></button>}
</div>}
function bannerTextShadow(s:any,kind:"title"|"description"){const color=kind==="title"?s.titleShadowColor:s.descriptionShadowColor;const blur=kind==="title"?s.titleShadowBlur:s.descriptionShadowBlur;const x=kind==="title"?s.titleShadowX:s.descriptionShadowX;const y=kind==="title"?s.titleShadowY:s.descriptionShadowY;const opacity=Number(kind==="title"?s.titleShadowOpacity:s.descriptionShadowOpacity);if(!color||opacity<=0)return "none";const alpha=Math.max(0,Math.min(1,opacity));return `${Number(x)||0}px ${Number(y)||0}px ${Number(blur)||0}px color-mix(in srgb,${color} ${alpha*100}%,transparent)`;}
